# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, offset=-1):
    return [v - offset for v in xs]

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, cut=3):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: digest
def digest(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return digest(sift(gather(emit(fold(raw)))))

